import{_ as e,o as a,c as o,ag as i}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"features/sessions.md","filePath":"features/sessions.md"}'),t={name:"features/sessions.md"};function n(r,s,l,d,c,p){return a(),o("div",null,[...s[0]||(s[0]=[i('<h1 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h1><p>Browse Claude Code conversation transcripts with full message details and tool use.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Sessions page displays conversation history from Claude Code sessions stored as JSONL files. You can filter by project and browse through conversations with paginated message views.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="browsing-sessions" tabindex="-1">Browsing Sessions <a class="header-anchor" href="#browsing-sessions" aria-label="Permalink to &quot;Browsing Sessions&quot;">​</a></h3><p>The session list shows all recorded conversations with:</p><ul><li>Session date and time</li><li>Message count</li><li>Project name</li></ul><p>Use the <strong>project filter</strong> dropdown to show sessions from a specific project or all projects.</p><h3 id="viewing-a-session" tabindex="-1">Viewing a Session <a class="header-anchor" href="#viewing-a-session" aria-label="Permalink to &quot;Viewing a Session&quot;">​</a></h3><p>Click a session to open the conversation viewer. Messages are displayed in order with:</p><ul><li><strong>User messages</strong> — your prompts</li><li><strong>Assistant messages</strong> — Claude&#39;s responses with full text</li><li><strong>Tool calls</strong> — tool name, arguments, and results</li><li><strong>Content blocks</strong> — code, text, and structured output</li></ul><p>Conversations are paginated (5 prompts per page) for performance.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Sessions are read-only. Claude Code stores transcripts as JSONL files in:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/projects/{project-folder}/*.jsonl</span></span></code></pre></div><p>Claude Deck caches parsed sessions in its database with a 5-minute TTL and file hash validation for fast page loads.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Sessions are <strong>read-only</strong> — you can browse but not modify transcripts.</li><li>The cache refreshes automatically when session files change on disk.</li><li>Filter by project to quickly find conversations for a specific codebase.</li></ul>',19)])])}const g=e(t,[["render",n]]);export{u as __pageData,g as default};
